{"code": "const res = await tools.pwsh({ description: "Remove my probe files and check for strays", command: `
$probes = Get-ChildItem -Path 'D:/lean/tmp/sheaf/xif/paper' -Filter '_S1854Probe*.lean'
$probes | ForEach-Object { $_.FullName }
foreach ($p in $probes) {
  $full = $p.FullName
  if ($full -like 'D:\\lean\\tmp\\sheaf\\xif\\paper\\_S1854Probe*.lean') { Remove-Item -LiteralPath $full -Force }
}
'--- after ---'
Get-ChildItem -Path 'D:/lean/tmp/sheaf/xif/paper' -Filter '*S1854*' | Select-Object Name,Length | Format-Table -AutoSize | Out-String
Get-ChildItem -Path 'D:/lean/.lake/build/lib/lean/tmp/sheaf/xif/paper' -Filter '*S1854*' | Select-Object Name,Length | Format-Table -AutoSize | Out-String
`});
console.log(res.kind === "foreground" ? res.stdout.text + res.stderr.text : JSON.stringify(res));
", "description": "Clean up probe files"}

